UPDATE content_entries
SET body_json = json_insert(body_json, '$[#]', json_object('type', 'html', 'html', '<h2>Ask specific questions</h2><p>Instead of asking only whether a dish is vegetarian, mention the ingredients you avoid and ask about broth, sauces, garnish and cooking method. If several people at the table have different needs, identify those needs before shared plates arrive. Clear questions help the team explain what is currently possible without relying on assumptions.</p><p>A useful order also includes enough protein and substance for the occasion. Legumes, yogurt, cheese, eggs or grains may contribute, depending on the selected dishes and the guest''s diet. Consider how long the meal needs to sustain the group rather than choosing only the lightest-looking plates.</p>'))
WHERE id = 'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb';

UPDATE content_entries
SET body_json = json_insert(body_json, '$[#]', json_object('type', 'html', 'html', '<h2>Compare how seasonings change</h2><p>Taste similar ingredients across two preparations when possible. Fresh mint in a salad behaves differently from dried mint cooked into a warm dish, and sumac added at the table differs from acidity developed throughout a sauce. Comparing those roles makes a shared meal more informative.</p>'))
WHERE id = 'cccccccc-cccc-4ccc-8ccc-cccccccccccc';

UPDATE content_entries
SET body_json = json_insert(body_json, '$[#]', json_object('type', 'html', 'html', '<h2>Make the morning comfortable</h2><p>Weather and the rest of the day can affect what feels practical. Guests carrying work bags, luggage or event materials may want to confirm where the group can meet before everyone arrives. Dress for the walk from transit or parking and keep important appointment details available offline.</p><p>When children or older relatives are joining, allow additional arrival time and ask about seating needs while reserving. A little planning protects the relaxed pace that makes a shared breakfast enjoyable, even when the group has another destination afterward.</p>'))
WHERE id = 'eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee';

UPDATE content_entries
SET body_json = json_insert(body_json, '$[#]', json_object('type', 'html', 'html', '<h2>Close the loop with guests</h2><p>Send a final message with the address, reservation time and organizer''s contact information. Ask guests to report cancellations promptly so the final party size stays accurate and the restaurant can prepare the appropriate table.</p>'))
WHERE id = 'ffffffff-ffff-4fff-8fff-ffffffffffff';